<section class="blade-panel" x-data="accountPreview"><p class="page-note">Pedidos ficticios para revisar el diseño. No corresponden al historial de tu cuenta.</p><div class="blade-table-wrap"><table class="blade-table"><caption class="sr-only">Pedidos de demostración</caption><thead><tr><th scope="col">Pedido</th><th scope="col">Fecha</th><th scope="col">Producto</th><th scope="col">Total</th><th scope="col">Estado</th><th scope="col">Detalle</th></tr></thead><tbody><template x-for="order in orders" :key="order.id"><tr><td x-text="order.id"></td><td x-text="order.date"></td><td x-text="order.item"></td><td x-text="order.total"></td><td x-text="order.status + ' · Demo'"></td><td><a class="text-button" :href="'/cuenta/pedidos/' + encodeURIComponent(order.id)">Ver ejemplo</a></td></tr></template></tbody></table></div></section>
